// One pass, two arrays, same order — the SQL join downstream is by position,
// so building them separately would silently pair the wrong phone with the
// wrong person.
//
// Bitrix returns PHONE as a list of typed values ([{VALUE, VALUE_TYPE}]); the
// first is the one the CRM shows. A contact with no phone contributes nothing
// rather than an empty pair, which would shift every later index by one.
const contacts = $input.first().json.result || [];
const pairs = [];
for (const c of contacts) {
  const raw = (c.PHONE || []).map(p => p && p.VALUE).find(v => v && String(v).trim());
  if (!raw) continue;
  pairs.push({ contact_id: String(c.ID), raw: String(raw) });
}
return [{ json: { pairs, values: pairs.map(p => p.raw), count: pairs.length } }];
